def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, objects = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack, cells = [(r, c)], []
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for a, b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= a < h and 0 <= b < w and (a,b) not in seen and grid[a][b] == color:
                        seen.add((a,b))
                        stack.append((a,b))
            rs = [x for x, y in cells]
            cs = [y for x, y in cells]
            objects.append({'color': color, 'cells': cells,
                            'box': (min(rs), min(cs), max(rs), max(cs)),
                            'edge': any(x in (0, h-1) or y in (0, w-1) for x, y in cells)})
    return objects


def _pattern(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return tuple(sorted((r-r0, c-c0) for r, c in cells))


def _is_l(obj):
    r0, c0, r1, c1 = obj['box']
    return r1 > r0 and c1 > c0 and len(obj['cells']) == (r1-r0+1) + (c1-c0+1) - 1


def transform(grid):
    out = [row[:] for row in grid]
    counts = {}
    for row in out:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)
    objects = _components(out, background)
    matches = []
    for frame in objects:
        if not frame['edge'] or not _is_l(frame):
            continue
        r0, c0, r1, c1 = frame['box']
        samples = [obj for obj in objects if obj is not frame and
                   all(r0 <= r <= r1 and c0 <= c <= c1 for r, c in obj['cells'])]
        for sample in samples:
            shape = _pattern(sample['cells'])
            for target in objects:
                if target is frame or target is sample:
                    continue
                if all(r0 <= r <= r1 and c0 <= c <= c1 for r, c in target['cells']):
                    continue
                if _pattern(target['cells']) == shape:
                    matches.append((len(sample['cells']), len(target['cells']), frame, target))
    if matches:
        _, _, frame, target = max(matches, key=lambda m: (m[0], m[1]))
        for r, c in target['cells']:
            out[r][c] = frame['color']
    return out
